sys_script_include.script:
var DriveFileAPI = Class.create();
DriveFileAPI.CONSTANTS = {
    API_CONFIG: {
        LIST: {
            path: "/drive/v3/files",
            httpMethod: "GET",
            queryParams: [
                "corpora",
                "driveId",
                "includeItemsFromAllDrives",
                "orderBy",
                "pageSize",
                "pageToken",
                "q",
                "spaces",
                "supportsAllDrives",
                "includePermissionsForView",
                "includeLabels"
            ],
            skipSystemAuth: true
        },
        GET: {
            path: "/drive/v3/files/${fileId}",
            httpMethod: "GET",
            pathParams: ["fileId"],
            queryParams: [
                "acknowledgeAbuse",
                "supportsAllDrives",
                "includePermissionsForView",
                "includeLabels"
            ],
            skipSystemAuth: true
        }
    }
};
DriveFileAPI.prototype = Object.extend(new x_neyu_google_nyu.RestUtil(), {
    initialize: function() {
        this.oauthProvider = "1b757d762bf08f10da0ef1bece91bfb2";
        this.providerProfile = "58c5bdb62bf08f10da0ef1bece91bf94";
        this.jwtProviderSysId = "4ea4b1762bf08f10da0ef1bece91bff7";
        this.credential = gs.getProperty("x_neyu_google_nyu.directory.api.credential.id");
        this.serviceAccount = gs.getProperty("x_neyu_google_nyu.drive.api.service.account");
        this.aliasId = "ec8ea13e2bb08f10da0ef1bece91bfa9";
        this.scopes = "https://www.googleapis.com/auth/drive.metadata.readonly";
    },

    /**
     * Lists or searches for files and folders in Google Drive.
     * * This method authenticates via OAuth and constructs a query against the Google Drive 
     * Files API. It supports pagination, searching via query strings, and shared drive access.
     * * @param {string} userEmail - the email address of the submitting user.
     * * @param {Object} [options={}] - Search and filter options.
     * @param {string} [options.corpora="user"] - Bodies of items (files/folders) to which the query applies. 
     * Supported values are 'user', 'domain', 'drive', and 'allDrives'.
     * @param {string} [options.driveId=null] - ID of the shared drive to query. Required if corpora is 'drive'.
     * @param {boolean} [options.includeItemsFromAllDrives=false] - Whether both My Drive and shared drive items should be included in results.
     * @param {string} [options.orderBy=null] - A comma-separated list of sort keys (e.g., 'name', 'modifiedTime', 'folder').
     * @param {number} [options.pageSize=100] - The maximum number of files to return per page. (Max: 1000).
     * @param {string} [options.pageToken=null] - The token for continuing a previous list request on the next page.
     * @param {string} [options.q=null] - A query string for filtering the file results (e.g., "name contains 'Project'").
     * @param {string} [options.spaces=null] - A comma-separated list of spaces to query of items to supported values are 'drive' and 'appDataFolder'.
     * @param {boolean} [options.supportsAllDrives=null] - Whether the requesting application supports both My Drive and shared drives.
     * @param {string} [options.includePermissionsForView=null] - Specifies which additional view's permissions to include (e.g., 'published').
     * @param {string} [options.includeLabels=null] - A comma-separated list of IDs of label types to include in the file metadata.
     * * @returns {Object} Standardized Response Object
     * @returns {boolean} return.error - True if the request failed.
     * @returns {number} return.status - The HTTP status code.
     * @returns {string} return.errorMessage - Description of the error.
     * @returns {string} return.responseBody - Raw JSON string. Contains `files` array and `nextPageToken`.
     * **Note:** Must be parsed using `JSON.parse()` before use.
     * * @example
     * // Search for all PDFs in the user's drive
     * const result = utils.listFiles({
     * q: "mimeType = 'application/pdf'",
     * pageSize: 10
     * });
     * * if (!result.error) {
     * const data = JSON.parse(result.responseBody);
     * data.files.forEach(file => gs.info(file.name));
     * }
     */
    listFiles: function(userEmail, {
        corpora = "user",
        driveId = null,
        includeItemsFromAllDrives = false,
        orderBy = null,
        pageSize = 100,
        pageToken = null,
        q = null,
        spaces = null,
        supportsAllDrives = null,
        includePermissionsForView = null,
        includeLabels = null,
		fields = null
    } = {}) {
        gs.info(`[listFiles] corpora: ${corpora}` +
            `\ndriveId: ${driveId}` +
            `\nincludesItemsFromAllDrives: ${includeItemsFromAllDrives}` +
            `\norderBy: ${orderBy}` +
            `\npageSize: ${pageSize}` +
            `\npageToken: ${pageToken}` +
            `\nq: ${q}` +
            `\nspaces: ${spaces}` +
            `\nsupportsAllDrives: ${supportsAllDrives}` +
            `\nincludePermissionsForView: ${includePermissionsForView}` +
			`\nfields: ${fields}` +
            `\nincludeLabels`);

        // this.ensureToken(this.credential, this.oauthProvider, this.providerProfile);
        const access_token = this.generateUserToken(
            userEmail,
            this.jwtProviderSysId,
            this.serviceAccount,
            this.scopes
        );

        const queryParams = {};
        if (!gs.nil(corpora)) {
            queryParams["corpora"] = corpora;
        }
        if (!gs.nil(driveId)) {
            queryParams["driveId"] = driveId;
        }
        if (!gs.nil(includeItemsFromAllDrives)) {
            queryParams["includeItemsFromAllDrives"] = includeItemsFromAllDrives;
        }
        if (!gs.nil(orderBy)) {
            queryParams["orderBy"] = orderBy;
        }
        if (!gs.nil(pageSize)) {
            queryParams["pageSize"] = pageSize;
        }
        if (!gs.nil(pageToken)) {
            queryParams["pageToken"] = pageToken;
        }
        if (!gs.nil(q)) {
            queryParams["q"] = q;
        }
        if (!gs.nil(spaces)) {
            queryParams["spaces"] = spaces;
        }
        if (!gs.nil(supportsAllDrives)) {
            queryParams["supportsAllDrives"] = supportsAllDrives;
        }
        if (!gs.nil(includePermissionsForView)) {
            queryParams["includePermissionsForView"] = includePermissionsForView;
        }
        if (!gs.nil(includeLabels)) {
            queryParams["includeLabels"] = includeLabels;
        }
		if (!gs.nil(fields)) {
			queryParams["fields"] = fields;
		}

        const headers = {
            "Accept": "application/json",
            "Content-Type": "application/json",
            "Authorization": `Bearer ${access_token}`
        };

        const config = DriveFileAPI.CONSTANTS.API_CONFIG.LIST;
        const requestConfig = {
            ...config,
            queryParams,
            headers,
            aliasId: this.aliasId
        };

        const response = this.execute(requestConfig, "listFiles");

        if (response.error) {
            gs.error("[listFiles] There was an error returned from " +
                "the Google Drive File API.\nResponse: " + JSON.stringify(response));
        }

        return {
            ...response
        };
    },

    /**
     * Gets a file's metadata by ID.
     * * This method retrieves specific file details. To download the actual file content, 
     * the 'alt=media' parameter is typically required, though this implementation 
     * focuses on metadata retrieval based on the provided configuration.
     * * @param {string} fileId - The ID of the file to retrieve.
     * * @param {string} userEmail - the email address of the submitting user.
     * @param {Object} [options={}] - Query parameters to modify the request.
     * @param {boolean} [options.acknowledgeAbuse=false] - Whether the user acknowledges the risk of downloading known malware or other abusive files. This is only applicable when retrieving file content.
     * @param {boolean} [options.supportsAllDrives=false] - Whether the requesting application supports both My Drive and shared drives.
     * @param {string} [options.includePermissionsForView=null] - Specifies which additional view's permissions to include (e.g., 'published').
     * @param {string} [options.includeLabels=null] - A comma-separated list of IDs of label types to include in the file metadata.
     * * @returns {Object} Standardized Response Object
     * @returns {boolean} return.error - True if the file ID is invalid or access is denied.
     * @returns {number} return.status - The HTTP status code (e.g., 200, 404).
     * @returns {string} return.errorMessage - Description of the error.
     * @returns {string} return.responseBody - Raw JSON string of the File resource metadata.
     * **Note:** Must be parsed using `JSON.parse()` before use.
     * * @example
     * const result = utils.getFile('1abc1234567890QWERTY', { 
     * supportsAllDrives: true 
     * });
     * * if (!result.error) {
     * const fileMetadata = JSON.parse(result.responseBody);
     * gs.info("File Name: " + fileMetadata.name);
     * gs.info("Mime Type: " + fileMetadata.mimeType);
     * }
     */
    getFile: function(fileId, userEmail, {
        acknowledgeAbuse = null,
        supportsAllDrives = null,
        includePermissionsForView = null,
        includeLabels = null
    } = {}) {
        gs.info(`[getFile] fileId: ${fileId}` +
            `\nQuery Parameters` +
            `\nacknowledgeAbuse: ${acknowledgeAbuse}` +
            `\nsupportsAllDrives: ${supportsAllDrives}` +
            `\nincludePermissionsForView: ${includePermissionsForView}` +
            `\nincludeLabels: ${includeLabels}`);

        const pathParams = {
            fileId: fileId
        };
        const queryParams = {};
        if (!gs.nil(acknowledgeAbuse)) {
            queryParams["acknowledgeAbuse"] = acknowledgeAbuse;
        }
        if (!gs.nil(supportsAllDrives)) {
            queryParams["supportsAllDrives"] = supportsAllDrives;
        }
        if (!gs.nil(includePermissionsForView)) {
            queryParams["includePermissionsForView"] = includePermissionsForView;
        }
        if (!gs.nil(includeLabels)) {
            queryParams["includeLabels"] = includeLabels;
        }

        // this.ensureToken(this.credential, this.oauthProvider, this.providerProfile);
        const access_token = this.generateUserToken(
            userEmail,
            this.jwtProviderSysId,
            this.serviceAccount,
            this.scopes
        );

        const headers = {
            "Accept": "application/json",
            "Content-Type": "application/json",
            "Authorization": `Bearer ${access_token}`
        };

        const config = DriveFileAPI.CONSTANTS.API_CONFIG.GET;
        const requestConfig = {
            ...config,
            pathParams,
            queryParams,
            headers,
            aliasId: this.aliasId
        };

        const response = this.execute(requestConfig, "getFile");

        if (response.error) {
            gs.error(`[getFile] There was an error returned from the ` +
                `Google Drive File API.\nResponse: ${JSON.stringify(response)}`);
        }

        return {
            ...response
        };
    },

    type: 'DriveFileAPI'
});
